/* Latin Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Marcus": "of Mars — Latin", "Julia": "youthful — Latin Julius", "Gaius": "rejoicing — Latin gaudere", "Augustus": "venerable, majestic — Latin", "Cornelia": "of horn — Latin cornu", "Livia": "The empress Livia's name, of the Livian gens.", "Julius": "The nomen of the Julian clan, Caesar's own.", "Cornelius": "The nomen of the Cornelian clan.", "Claudius": "The nomen of the Claudian clan.", "Valerius": "The nomen of the Valerian clan."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Marcus';
console.log(lookup(q));

